import { readFile, writeFile, mkdir } from "node:fs/promises";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

// No build dependency: run from any directory with Node. Generated files are
// tracked so both the static Angular build and the mounted Keycloak theme work.
const root = fileURLToPath(new URL("../", import.meta.url));
const check = process.argv.includes("--check");
if (process.argv.slice(2).some(arg => arg !== "--check")) {
  throw new Error("Usage: node scripts/sync-branding.mjs [--check]");
}
const tokens = JSON.parse(await readFile(resolve(root, "design/branding.json"), "utf8"));
const css = "/* Generated by scripts/sync-branding.mjs. Edit design/branding.json. */\n:root {\n"
  + Object.entries(tokens).map(([key, value]) => `  --telecom-${key}: ${value};`).join("\n")
  + "\n}\n";
// Decorative mark; the adjacent, real brand text supplies the accessible name.
const svg = `<!-- Generated by scripts/sync-branding.mjs. Edit design/branding.json. -->
<svg xmlns="http://www.w3.org/2000/svg" width="36" height="36" viewBox="0 0 36 36">
  <path fill="${tokens.primary}" d="M0 0h36v36H0z"/>
  <path fill="${tokens.surface}" d="M11 10h14v4h-5v12h-4V14h-5z"/>
</svg>
`;
const outputs = [
  ["apps/dashboard/src/branding/tokens.css", css],
  ["infra/keycloak/themes/telecom/login/resources/css/tokens.css", css],
  ["apps/dashboard/src/branding/mark.svg", svg],
  ["infra/keycloak/themes/telecom/login/resources/img/mark.svg", svg],
];
for (const [path, contents] of outputs) {
  const target = resolve(root, path);
  if (check) {
    const actual = await readFile(target, "utf8").catch(() => "");
    if (actual !== contents) {
      console.error(`Stale branding: ${path}. Run node scripts/sync-branding.mjs`);
      process.exitCode = 1;
    }
  } else {
    await mkdir(dirname(target), { recursive: true });
    await writeFile(target, contents);
  }
}
if (!process.exitCode) console.log(check ? "Shared branding is current." : "Shared branding generated.");
